package co.parikshit.otakudub

import org.json.JSONObject
import java.io.File

/**
 * Encodes phonemes into IDs using the matching Piper voice config.
 *
 * IMPORTANT:
 * Input must contain phonemes generated by a compatible
 * phonemizer, not ordinary written text.
 */
class PiperPhonemeEncoder(
    configFile: File
) {
    private val phonemeIdMap: Map<String, LongArray>

    private val padId: Long
    private val bosId: Long
    private val eosId: Long

    init {
        require(configFile.isFile) {
            "Piper configuration file does not exist."
        }

        val root = JSONObject(configFile.readText())

        val rawMap = root.optJSONObject("phoneme_id_map")
            ?: error("Piper phoneme_id_map is missing.")

        require(rawMap.length() > 0) {
            "Piper phoneme_id_map is empty."
        }

        val parsed = mutableMapOf<String, LongArray>()

        val keys = rawMap.keys()

        while (keys.hasNext()) {
            val phoneme = keys.next()
            val values = rawMap.getJSONArray(phoneme)

            require(values.length() > 0) {
                "Empty phoneme ID sequence: $phoneme"
            }

            val ids = LongArray(values.length())

            for (index in 0 until values.length()) {
                val value = values.get(index)

                require(value is Number) {
                    "Invalid phoneme ID for $phoneme."
                }

                val id = value.toLong()

                require(id >= 0L && id.toDouble() == value.toDouble()) {
                    "Phoneme IDs must be non-negative integers."
                }

                ids[index] = id
            }

            parsed[phoneme] = ids
        }

        phonemeIdMap = parsed.toMap()

        padId = specialId("_")
        bosId = specialId("^")
        eosId = specialId("$")
    }

    private fun specialId(symbol: String): Long {
        val ids = phonemeIdMap[symbol]
            ?: error("Required Piper symbol is missing: $symbol")

        require(ids.size == 1) {
            "Invalid special-symbol mapping: $symbol"
        }

        return ids[0]
    }

    /**
     * Encode a phoneme sequence in Piper's standard format:
     *
     * BOS, PAD, phoneme IDs separated by PAD, EOS.
     *
     * Each supplied string is expected to represent one phoneme
     * symbol in the selected model's phoneme_id_map.
     */
    fun encode(phonemes: List<String>): LongArray {
        require(phonemes.isNotEmpty()) {
            "Cannot encode an empty phoneme sequence."
        }

        val output = ArrayList<Long>()

        output.add(bosId)
        output.add(padId)

        for (phoneme in phonemes) {
            require(phoneme.isNotEmpty()) {
                "An empty phoneme was supplied."
            }

            val ids = phonemeIdMap[phoneme]
                ?: error(
                    "Phoneme is unsupported by this voice model: $phoneme"
                )

            for (id in ids) {
                output.add(id)
                output.add(padId)
            }
        }

        output.add(eosId)

        require(output.size <= 16384) {
            "Encoded phoneme sequence exceeds the safety limit."
        }

        return output.toLongArray()
    }

    /**
     * Splits a Unicode phoneme string into code-point symbols.
     *
     * This is appropriate only when the phonemizer's output
     * convention matches the model's phoneme_id_map.
     *
     * It does not perform grapheme-to-phoneme conversion.
     */
    fun encodeCodePoints(
        phonemeText: String
    ): LongArray {
        require(phonemeText.isNotBlank()) {
            "Phoneme text cannot be empty."
        }

        val symbols = ArrayList<String>()

        var offset = 0

        while (offset < phonemeText.length) {
            val codePoint = phonemeText.codePointAt(offset)

            symbols.add(
                String(Character.toChars(codePoint))
            )

            offset += Character.charCount(codePoint)
        }

        return encode(symbols)
    }

    fun supports(phoneme: String): Boolean {
        return phonemeIdMap.containsKey(phoneme)
    }

    fun supportedSymbolCount(): Int {
        return phonemeIdMap.size
    }
}
